-- Remaining squad profiles, editable catalogs and screening questions.
BEGIN;
ALTER TABLE talent_users DROP CONSTRAINT IF EXISTS talent_users_signup_form_type_check;
ALTER TABLE talent_users ADD CONSTRAINT talent_users_signup_form_type_check CHECK (signup_form_type IS NULL OR signup_form_type IN ('creative','accountant','sales','creative_director','copy_content_writer','social_media_manager','videographer','photographer','videographer_photographer','ai_video_image_creator','ads_specialist','seo_specialist','digital_marketing_team','influencer_marketing','offline_marketing','web_development','app_building','automation','software_solutions','cfo_ca','gst_experts','tds_experts','labour_law','incorporation','contract_drafting','ip_protection','compliance','business_formation','end_to_end_hiring','team_building','hr_process'));

-- Stable cross-project links must never silently target a different category.
DO $$ BEGIN
IF EXISTS(SELECT 1 FROM categories c JOIN (VALUES ('seo-specialist','ca148002-5800-4800-8800-000000000001'::uuid),('digital-marketing-team','ca148002-5800-4800-8800-000000000002'::uuid),('influencer-marketing','ca148002-5800-4800-8800-000000000003'::uuid),('offline-marketing','ca148002-5800-4800-8800-000000000004'::uuid),('web-development','ca148002-5800-4800-8800-000000000005'::uuid),('app-building','ca148002-5800-4800-8800-000000000006'::uuid),('automation','ca148002-5800-4800-8800-000000000007'::uuid),('software-solutions','ca148002-5800-4800-8800-000000000008'::uuid),('cfo-ca','ca148002-5800-4800-8800-000000000009'::uuid),('gst-experts','ca148002-5800-4800-8800-000000000010'::uuid),('tds-experts','ca148002-5800-4800-8800-000000000011'::uuid),('labour-law','ca148002-5800-4800-8800-000000000012'::uuid),('incorporation','ca148002-5800-4800-8800-000000000013'::uuid),('contract-drafting','ca148002-5800-4800-8800-000000000014'::uuid),('ip-protection','ca148002-5800-4800-8800-000000000015'::uuid),('compliance','ca148002-5800-4800-8800-000000000016'::uuid),('business-formation','ca148002-5800-4800-8800-000000000017'::uuid),('end-to-end-hiring','ca148002-5800-4800-8800-000000000018'::uuid),('team-building','ca148002-5800-4800-8800-000000000019'::uuid),('hr-process','ca148002-5800-4800-8800-000000000020'::uuid)) expected(slug,id) ON c.slug=expected.slug WHERE c.id<>expected.id) THEN RAISE EXCEPTION 'An existing squad category uses a different ID. Reconcile its cross-project catalog link before applying this migration.'; END IF;
END $$;

COMMIT;
NOTIFY pgrst, 'reload schema';
